engine.command:
docker create --label io.pg_qdrant.ci.lifecycle=1 --label io.pg_qdrant.ci=${PGQ_RUN_ID} --name pg-qdrant-p0-helper-normal-run-${PGQ_RUN_ID} --memory=5g --cpus=2 --network=none \
  pg-qdrant-p0-helper-normal-${PGQ_RUN_ID} bash crates/pg_qdrant/tests/run-p0.sh
docker start --attach pg-qdrant-p0-helper-normal-run-${PGQ_RUN_ID}

docker create --label io.pg_qdrant.ci.lifecycle=1 --label io.pg_qdrant.ci=${PGQ_RUN_ID} --name pg-qdrant-p0-helper-run-${PGQ_RUN_ID} --memory=5g --cpus=2 --network=none \
  pg-qdrant-p0-helper-${PGQ_RUN_ID} bash crates/pg_qdrant/tests/run-faults.sh
docker start --attach pg-qdrant-p0-helper-run-${PGQ_RUN_ID}

docker create --label io.pg_qdrant.ci.lifecycle=1 --label io.pg_qdrant.ci=${PGQ_RUN_ID} --name pg-qdrant-p1-product-${PGQ_RUN_ID} --memory=5g --cpus=2 --network=none \
  pg-qdrant-p0-helper-${PGQ_RUN_ID} bash crates/pg_qdrant/tests/run-p1.sh
docker start --attach pg-qdrant-p1-product-${PGQ_RUN_ID}

ledger.command:
docker create --label io.pg_qdrant.ci.lifecycle=1 --label io.pg_qdrant.ci=${PGQ_RUN_ID} --name pg-qdrant-p1-run-${PGQ_RUN_ID} --memory=5g --cpus=2 --network=none \
  pg-qdrant-p1-base-${PGQ_RUN_ID} bash experiments/p1-ledger/run.sh
docker start --attach pg-qdrant-p1-run-${PGQ_RUN_ID}
